                         'let force = 10.0<N>\n'
                         'let area = 16.0<m^2>\n'
                         'let vol = 27.0<m^3>\n'
                         'let pure rate d = d / 1.0<s>\n'
                         'let fetch k = async { return k * 2 }\n'
                         'let fetchTwice k =\n'
                         '  async {\n'
