@pytest.mark.parametrize("case", EFFECT_CASES, ids=[c["id"] for c in EFFECT_CASES])
def test_effects_units_async_and_state_across_modules(run, workdir, case):
    """CATCHES: effects, units, async values or mutable state that cross a module boundary
    (directly, through a re-exporting module, or by two paths) inferred, reported,
    emitted or run differently from the reference."""
    S.check(run, workdir, case, __file__)
